#include <cuda_runtime.h>
#include <vector>
#include <algorithm>
#define main legacy_main
#include "../particle-diffusion-cuda/motionsim.cu"
#undef main
#define CK(x) do{auto e=(x);if(e!=cudaSuccess){fprintf(stderr,"%s\n",cudaGetErrorString(e));exit(1);}}while(0)
int main(int argc,char**argv){int n=4096,steps=32,g=21,repeat=argc>1?atoi(argv[1]):10;float radius=.5f;std::vector<float>x0(n),y0(n),rx(n*steps),ry(n*steps),ex,ey,gx(n),gy(n);for(int i=0;i<n;i++){x0[i]=float(i%21)+float(35+64*(i%4))/256.f;y0[i]=float((i/21)%21)+float(35+64*((i/4)%4))/256.f;if(i<64)x0[i]=(i+1)%2?-.25f:21.25f;}for(int step=0;step<steps;step++)for(int i=0;i<n;i++){rx[step*n+i]=1000.f*(.0495f+float((i*13+step*7)%17-8)/1024.f);ry[step*n+i]=1000.f*(.0495f+float((i*37+step*11)%17-8)/1024.f);}ex=x0;ey=y0;std::vector<size_t>em(n*g*g,0),gm(em.size());reference(ex.data(),ey.data(),rx.data(),ry.data(),em.data(),n,steps,g,radius);float *dx,*dy,*drx,*dry;size_t*dm;CK(cudaMalloc(&dx,n*4));CK(cudaMalloc(&dy,n*4));CK(cudaMalloc(&drx,rx.size()*4));CK(cudaMalloc(&dry,ry.size()*4));CK(cudaMalloc(&dm,em.size()*8));CK(cudaMemcpy(drx,rx.data(),rx.size()*4,cudaMemcpyHostToDevice));CK(cudaMemcpy(dry,ry.data(),ry.size()*4,cudaMemcpyHostToDevice));auto reset=[&](){CK(cudaMemcpy(dx,x0.data(),n*4,cudaMemcpyHostToDevice));CK(cudaMemcpy(dy,y0.data(),n*4,cudaMemcpyHostToDevice));CK(cudaMemset(dm,0,em.size()*8));CK(cudaDeviceSynchronize());};auto launch=[&](){Simulation<<<n/256,256>>>(dx,dy,drx,dry,dm,n,steps,g,radius);};reset();launch();CK(cudaDeviceSynchronize());bool all=true;for(int trial=1;trial<=5;trial++){double elapsed=0;for(int rep=0;rep<repeat;rep++){reset();auto t0=std::chrono::steady_clock::now();launch();CK(cudaDeviceSynchronize());elapsed+=std::chrono::duration<double>(std::chrono::steady_clock::now()-t0).count()/repeat;}CK(cudaMemcpy(gx.data(),dx,n*4,cudaMemcpyDeviceToHost));CK(cudaMemcpy(gy.data(),dy,n*4,cudaMemcpyDeviceToHost));CK(cudaMemcpy(gm.data(),dm,gm.size()*8,cudaMemcpyDeviceToHost));float ma=0;for(int i=0;i<n;i++)ma=fmaxf(ma,fmaxf(fabsf(gx[i]-ex[i]),fabsf(gy[i]-ey[i])));bool countok=gm==em,ok=countok&&ma<=1e-5f;all&=ok;std::vector<double>output;for(float x:gx)output.push_back(x);for(float y:gy)output.push_back(y);for(size_t v:gm)output.push_back(double(v));char file[100];sprintf(file,"particle_trial%d.bin",trial);FILE*f=fopen(file,"wb");fwrite(output.data(),8,output.size(),f);fclose(f);printf("STUDY_TRIAL {\"trial\":%d,\"time_seconds\":%.12g,\"correct\":%s,\"checked_values\":%d,\"max_abs_error\":%.12g,\"max_rel_error\":0,\"counts_exact\":%s,\"timing_region\":\"one_32step_particle_simulation_kernel_resets_excluded\",\"jit_excluded\":true,\"internal_repeats\":%d,\"output_artifact\":{\"path\":\"%s\",\"dtype\":\"float64\",\"count\":%d,\"byte_order\":\"little\"}}\n",trial,elapsed,ok?"true":"false",int(output.size()),ma,countok?"true":"false",repeat,file,int(output.size()));}CK(cudaFree(dx));CK(cudaFree(dy));CK(cudaFree(drx));CK(cudaFree(dry));CK(cudaFree(dm));puts(all?"PASS":"FAIL");return all?0:1;}
